module sequence_detector #(
    parameter IDLE = 5'b00001,
    parameter S1   = 5'b00010,
    parameter S2   = 5'b00100,
    parameter S3   = 5'b01000,
    parameter S4   = 5'b10000
) (
    input  clk,
    input  rst_n,
    input  data_in,
    output sequence_detected
);


reg [2:0] current_state, next_state;

always @(posedge clk or posedge reset_n) begin
    if (reset_n == 1'b1) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end
always @(*) begin
    case(current_state)
        IDLE: begin
            if(data_in == 1'b1) next_state = S1; else next_state = IDLE;
        end

        S1: begin
            if(data_in == 1'b0) next_state = S2; else next_state = IDLE;
        end

        S2: begin
            if(data_in == 1'b0) next_state = S3; else next_state = IDLE;
        end

        S3: begin
            if(data_in == 1'b1) next_state = S4; else next_state = IDLE;
        end

        S4: begin
            if(data_in == 1'b1) next_state = IDLE; else next_state = IDLE;
        end

        default: next_state = IDLE;
    endcase
end

assign sequence_detected = (current_state == S4 && data_in == 1'b1);
endmodule
